function validate([workers, bikes]) {
  if (!Array.isArray(workers) || workers.length < 1 || workers.length > 1000) return 'workers needs 1 to 1000 positions.';
  if (!Array.isArray(bikes) || bikes.length < workers.length || bikes.length > 1000) return 'bikes needs at least as many positions as workers, and at most 1000.';
  const seen = new Set();
  for (const point of [...workers, ...bikes]) {
    if (!Array.isArray(point) || point.length !== 2) return 'Each position is a pair [x, y].';
    if (point.some(v => !Number.isInteger(v) || v < 0 || v > 999)) return 'Coordinates are whole numbers from 0 to 999.';
    const key = point[0] * 1000 + point[1];
    if (seen.has(key)) return 'All worker and bike positions must be different.';
    seen.add(key);
  }
  return null;
}

