function assignBikes(workers, bikes) {
  const buckets = [];

  for (let w = 0; w < workers.length; w++) {
    for (let b = 0; b < bikes.length; b++) {
      const distance = Math.abs(workers[w][0] - bikes[b][0]) + Math.abs(workers[w][1] - bikes[b][1]);
      while (buckets.length <= distance) {
        buckets.push([]);
      }
      buckets[distance].push([w, b]);
    }
  }

  const answer = new Array(workers.length).fill(-1);
  const taken = new Array(bikes.length).fill(false);
  let assigned = 0;

  for (const bucket of buckets) {
    for (const [w, b] of bucket) {
      if (answer[w] !== -1 || taken[b]) {
        continue;
      }
      answer[w] = b;
      taken[b] = true;
      assigned++;
      if (assigned === workers.length) {
        return answer;
      }
    }
  }
  return answer;
}

