function assignBikes(workers, bikes) {
  // Simulate the rule literally: each round scans every free pair and keeps the first strictly closer one.
  const answer = new Array(workers.length).fill(-1);
  const used = new Set();
  for (let round = 0; round < workers.length; round++) {
    let best = null;
    for (let i = 0; i < workers.length; i++) {
      if (answer[i] !== -1) continue;
      for (let j = 0; j < bikes.length; j++) {
        if (used.has(j)) continue;
        const d = Math.abs(workers[i][0] - bikes[j][0]) + Math.abs(workers[i][1] - bikes[j][1]);
        if (best === null || d < best[0]) best = [d, i, j];
      }
    }
    answer[best[1]] = best[2];
    used.add(best[2]);
  }
  return answer;
}

