function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(200, 400) : int(1, 4);
  const m = size === 'large' ? int(Math.max(n, 600), 1000) : int(n, 6);
  // A small span packs the points together, which creates many equal distances and ties.
  const span = size === 'large' ? (rand() < 0.5 ? 1000 : 60) : (rand() < 0.6 ? 4 : 1000);
  const base = int(0, 1000 - span);
  const used = new Set();
  const point = () => {
    for (;;) {
      const x = base + int(0, span - 1), y = base + int(0, span - 1);
      if (!used.has(x * 1000 + y)) { used.add(x * 1000 + y); return [x, y]; }
    }
  };
  const workers = Array.from({ length: n }, point);
  const bikes = Array.from({ length: m }, point);
  return [workers, bikes];
}
